import {attackStyle} from './attack-fx.mjs';
import {drawFlight,drawStream,drawWave,drawCharge,drawImpact,drawPixel} from './pixel-fx.mjs';
import {survivalSupport,survivalPower} from './survival-strategy.mjs';
import {direction} from './art.mjs';
const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
const segment=(p,a,b)=>{const x=b.x-a.x,y=b.y-a.y,t=clamp(((p.x-a.x)*x+(p.y-a.y)*y)/(x*x+y*y||1));return Math.hypot(p.x-a.x-x*t,p.y-a.y-y*t)};
export function castSurvival(c,targets){const r=c.r,slot=r.slot,m=r.moves[slot];if(!m)return;if(m.status){survivalSupport(c,m,targets);return}if(!targets.length)return;const style=attackStyle(m),target=targets.reduce((a,b)=>Math.hypot(a.x-r.x,a.y-r.y)<Math.hypot(b.x-r.x,b.y-r.y)?a:b),angle=Math.atan2(target.y-r.y,target.x-r.x),stream=['flame','water'].includes(style.kind)&&/thrower|blast|pump|gun|cannon/.test(style.id);if(slot===2&&!['beam','wave'].includes(style.kind)&&!targets.some(e=>Math.hypot(e.x-r.x,e.y-r.y)<105))return;
 const kind=style.kind==='beam'||style.kind==='lightning'?'beam':stream?'stream':style.kind==='wave'?'wave':slot===2?'zone':'orb',base=(16+m.power*.32)*r.power*survivalPower(c,m),deltas=kind==='orb'&&slot===1?[-.2,0,.2]:[0];r.attackStart=r.time;r.attackUntil=r.time+.4;r.attackDir=direction(target.x-r.x,target.y-r.y);r.cooldowns[slot]=Math.max([.48,.9,1.45,1.3][slot],kind==='beam'?1.15:kind==='wave'?1.3:.4)*r.cadence;
 for(const delta of deltas){const a=angle+delta,speed=kind==='wave'?240:slot===3?520:330,delay=kind==='beam'||kind==='stream'?.16:kind==='zone'?.18:.08;r.bullets.push({id:++r.uid,kind,move:m,type:m.type,from:{x:r.x,y:r.y},x:r.x,y:r.y,dx:Math.cos(a)*speed,dy:Math.sin(a)*speed,speed,angle:a,damage:base*(kind==='beam'?1.25:kind==='zone'?1.4:deltas.length>1?.65:slot===3?1.3:1),age:0,delay,range:kind==='zone'?105:r.vision+30,life:kind==='beam'||kind==='stream'?.85:kind==='zone'?.65:kind==='wave'?1.4:1,hit:new Set(),radius:kind==='wave'?40:17,pierce:kind==='wave'||slot===3,trail:[]})}c.g.audio.attack(m.type);
}
export function stepSurvivalShots(c,dt){const r=c.r;for(const b of r.bullets){b.age=(b.age||0)+dt;b.life-=dt;if(b.age<(b.delay||0))continue;
 if(b.kind==='beam'||b.kind==='stream'){// The growing head and collision use exactly the same endpoint.
  b.from={x:r.x,y:r.y};const reach=b.range*clamp((b.age-b.delay)/.24);b.end={x:b.from.x+Math.cos(b.angle)*reach,y:b.from.y+Math.sin(b.angle)*reach};for(const e of r.enemies)if(e.hp>0&&!b.hit.has(e.uid)&&segment(e,b.from,b.end)<19){b.hit.add(e.uid);c.hurt(e,b.damage,b.type,b.move)}
 }else if(b.kind==='zone'){const radius=Math.min(b.range,(b.age-b.delay)/.25*b.range);for(const e of r.enemies)if(e.hp>0&&!b.hit.has(e.uid)&&Math.hypot(e.x-b.x,e.y-b.y)<radius){b.hit.add(e.uid);c.hurt(e,b.damage,b.type,b.move)}}
 else{const before={x:b.x,y:b.y};b.x+=b.dx*dt;b.y+=b.dy*dt;for(const e of r.enemies)if(e.hp>0&&b.life>0&&!b.hit.has(e.uid)&&segment(e,before,b)<(b.radius||21)){b.hit.add(e.uid);c.hurt(e,b.damage,b.type,b.move);if(!b.pierce)b.life=0}}}r.bullets=r.bullets.filter(b=>b.life>0)}
export function drawSurvivalShots(c,r,cx,cy,reduced){for(const b of r.bullets){const from={x:b.from.x-cx,y:b.from.y-cy},at={x:b.x-cx,y:b.y-cy};if(b.age<b.delay){drawCharge(c,b.move,from,b.age/b.delay,{scale:.7,reducedMotion:reduced});continue}if(b.kind==='beam'||b.kind==='stream'){const end=b.end||b.from;drawStream(c,b.move,from,{x:end.x-cx,y:end.y-cy},r.time,{width:b.kind==='beam'?16:13,reducedMotion:reduced})}else if(b.kind==='wave')drawWave(c,b.move,at,b.angle,r.time,{width:95,reducedMotion:reduced});else if(b.kind==='zone'){const t=clamp((b.age-b.delay)/.45);drawPixel(c,'slash',b.type,at.x,at.y,130,t,r.time*4,{once:true,alpha:1-t});drawImpact(c,b.move,at,t,{scale:1.2,reducedMotion:reduced})}else drawFlight(c,b.move,at,b.angle,r.time,{size:52,reducedMotion:reduced})}}
export function captureSurvival(r){return {...r,enemies:r.enemies.map(e=>({...e})),bullets:r.bullets.map(b=>({...b,from:b.from&&{...b.from},end:b.end&&{...b.end}})),effects:r.effects.map(e=>({...e})),attackFX:r.attackFX.map(e=>({...e})),gems:r.gems.map(e=>({...e}))}}
export function interpolateSurvival(old,r,alpha){if(!old||old.key!==r.key)return r;const t=clamp(alpha),mix=(a,b)=>a+(b-a)*t,bodies=(a,b,id)=>{const next=new Map(b.map(e=>[e[id],e]));return a.map(e=>{const n=next.get(e[id]);if(!n)return e;next.delete(e[id]);return {...n,x:mix(e.x,n.x),y:mix(e.y,n.y),age:Number.isFinite(e.age)&&Number.isFinite(n.age)?mix(e.age,n.age):n.age,from:e.from&&n.from?{x:mix(e.from.x,n.from.x),y:mix(e.from.y,n.from.y)}:n.from,end:e.end&&n.end?{x:mix(e.end.x,n.end.x),y:mix(e.end.y,n.end.y)}:n.end}}).concat([...next.values()])};return {...old,time:mix(old.time,r.time),x:mix(old.x,r.x),y:mix(old.y,r.y),effects:old.effects.map(e=>({...e,life:Math.max(0,e.life-(r.time-old.time)*t)})),enemies:bodies(old.enemies,r.enemies,'uid'),bullets:bodies(old.bullets,r.bullets,'id'),attackFX:r.attackFX.map(e=>({...e,age:Math.max(0,e.age-(r.time-old.time)*(1-t))}))}}
